// flow_walk.js — step-through animation for the arena's lane-flow figures.
// The mermaid SVGs stay generated bytes (render_tetris_flows.py renders them
// from katgpt-rs tetris_lane_flows.md — never hand-edited); this module
// inlines a figure's SVG in place of its <img>, walks the flow blocks one
// step at a time (autoplay 3 s per step once the figure scrolls into view;
// manual restart / prev / play-pause / next / dot-jump), and explains each
// step in a panel below the graphic. The <img> stays the no-JS fallback:
// the swap only happens after a successful fetch, and any failure leaves
// the static figure exactly as it was. Highlight overrides are inline
// styles (JS) + plain classes (arena.css) so nothing fights the SVG's own
// id-scoped mermaid rules. Palette: ember/rust only — the site theme bans
// yellow.

const STEP_MS = 3000;

// Step scripts. `nodes` are mermaid node-id suffixes (the SVG prefixes them
// with its own id); `edges` are mermaid edge ids (path + its edgeLabel).
const WALKS = {
  "tetris_flow_rulebook.svg": {
    intro:
      "No model, no sentences — the rulebook lane searches placements and scores boards with a fixed strategy rulebook. Press play to walk the six steps, or click a dot to jump.",
    steps: [
      {
        nodes: ["flowchart-A-0"],
        title: "Look ahead — the falling piece",
        text: "The rulebook never reacts one piece at a time. It starts by listing every legal landing spot for the piece in play — every rotation in every column — and treats each one as a possible future board.",
      },
      {
        nodes: ["flowchart-B-1"],
        edges: ["L_A_B_0"],
        title: "Chain the preview piece",
        text: "Each candidate board is paired with every landing spot of the preview piece — and the tree is pruned hard: only the best six boards survive each level, so the search stays tiny instead of exploding.",
      },
      {
        nodes: ["flowchart-C-2"],
        edges: ["L_B_C_0"],
        title: "Cover the unknown third piece",
        text: "The piece after that is not known yet. Rather than gamble on a single guess, the plan plays out every piece still left in the 7-bag — the search branches over whatever the bag could still deal.",
      },
      {
        nodes: ["flowchart-V-3"],
        edges: ["L_C_V_0"],
        title: "Score every end board",
        text: "Each final board is scored by the strategy rulebook — holes, bumpiness, stack height, wells, lines cleared — the instincts of a careful human player, written as numbers.",
      },
      {
        nodes: ["flowchart-G-4"],
        edges: ["L_V_G_0"],
        title: "Average over the unknown · pick the plan",
        text: "A plan is only as good as its worst realistic draw: scores are averaged across the possible third pieces, so a line-clear that needs the I-piece rates low — it usually does not come. The sturdiest plan wins.",
      },
      {
        nodes: ["flowchart-P-5"],
        edges: ["L_G_P_0"],
        title: "Play the first move — then re-plan",
        text: "Only the winning plan's first move is played; the very next piece restarts the whole search from scratch. All of it runs in about 0.35 ms — a thousand-plus searches would fit inside one 60 Hz frame.",
      },
    ],
  },
  "tetris_flow_modes.svg": {
    intro:
      "Before every piece the rulebook re-reads the board and picks a mode. Press play to walk the full build → trouble → recover cycle, or click a dot to jump.",
    steps: [
      {
        nodes: ["flowchart-BU-0"],
        title: "BUILD — the default mode",
        text: "On a clean, low stack it builds a 9-1 stack: nine columns packed flat plus one open well on the right edge, saving I-pieces to clear four lines at once. The 9-1 shape was self-evolved — nobody hand-coded it; it fell out of the training climb.",
      },
      {
        nodes: ["flowchart-DS-1"],
        edges: ["L_BU_DS_0"],
        title: "Trouble #1 — covered holes → DOWNSTACK",
        text: "Three or more holes buried under the stack and building stops paying: every new piece makes it worse. The mode flips to DOWNSTACK, which deliberately clears the lines sitting above the holes to dig them back out.",
      },
      {
        nodes: ["flowchart-SV-2"],
        edges: ["L_BU_SV_0"],
        title: "Trouble #2 — tall stack → SURVIVE",
        text: "A stack twelve rows high is one bad piece from topping out. SURVIVE takes any line it can and keeps the board low — scoring gives way to staying alive. (Survive wins when both exits fire at once.)",
      },
      {
        nodes: ["flowchart-BU-0"],
        edges: ["L_DS_BU_0", "L_SV_BU_0"],
        title: "Recovery — both modes hand back to BUILD",
        text: "Holes dug out, or the stack back under twelve — either way the mode returns to BUILD and the cycle starts over. The board is re-read before every single piece, so the switch is never late.",
      },
      {
        nodes: ["flowchart-BU-0", "flowchart-DS-1", "flowchart-SV-2"],
        title: "One search, three weights",
        text: "The modes are not three different AIs — it is the same placement search wearing different score weights: self-evolved builder weights while safe, proven survival weights in trouble. That is the whole trick behind the rulebook lane.",
      },
    ],
  },
};

const ACTIVE_STROKE = "#ffb27a"; // light ember tint — brighter than the default border
const ACTIVE_FILL = "#331d13"; // lifted node fill
const EMBER = "#ff8a4c";

function el(tag, cls, text) {
  const n = document.createElement(tag);
  if (cls) n.className = cls;
  if (text != null) n.textContent = text;
  return n;
}

function setupWalk(figure, svg, svgId, cfg) {
  svg.style.maxWidth = ""; // mermaid inlines its own; page CSS owns sizing
  const nodeId = (suffix) => svg.querySelector("#" + CSS.escape(svgId + "-" + suffix));
  const edgePath = (id) => svg.querySelector("#" + CSS.escape(svgId + "-" + id));
  const edgeLabel = (id) => {
    const label = svg.querySelector('g.label[data-id="' + id + '"]');
    return label ? label.closest(".edgeLabel") : null;
  };

  // first step index each node appears in — the "visited" (fw-done) test
  const firstSeen = new Map();
  cfg.steps.forEach((s, i) => s.nodes.forEach((n) => {
    if (!firstSeen.has(n)) firstSeen.set(n, i);
  }));

  const stage = el("div", "fw-stage");
  stage.appendChild(svg);

  const controls = el("div", "fw-controls");
  controls.setAttribute("role", "group");
  controls.setAttribute("aria-label", "Flow playback controls");
  const bRestart = el("button", "fw-btn", "↺");
  bRestart.type = "button";
  bRestart.title = "Restart from the first step";
  bRestart.setAttribute("aria-label", "Restart from the first step");
  const bPrev = el("button", "fw-btn", "◀");
  bPrev.type = "button";
  bPrev.setAttribute("aria-label", "Previous step");
  const bToggle = el("button", "fw-btn fw-toggle", "play");
  bToggle.type = "button";
  bToggle.setAttribute("aria-label", "Play");
  const bNext = el("button", "fw-btn", "▶"); // next uses a hollow triangle via CSS
  bNext.type = "button";
  bNext.classList.add("fw-next");
  bNext.setAttribute("aria-label", "Next step");
  const dots = el("span", "fw-dots");
  const dotEls = cfg.steps.map((s, i) => {
    const d = el("button", "fw-dot");
    d.type = "button";
    d.setAttribute("aria-label", "Step " + (i + 1) + ": " + s.title);
    d.addEventListener("click", () => { pause(); go(i); });
    dots.appendChild(d);
    return d;
  });
  const count = el("span", "fw-count");
  controls.append(bRestart, bPrev, bToggle, bNext, dots, count);

  const panel = el("div", "fw-step");
  panel.setAttribute("role", "status");
  const pTitle = el("b", "fw-step-title");
  const pText = el("p", "fw-step-text");
  panel.append(pTitle, pText);

  let cur = -1; // -1 = intro: nothing highlighted yet
  let playing = false;
  let timer = null;

  function clearInline(node) {
    node.style.stroke = "";
    node.style.strokeWidth = "";
    node.style.fill = "";
    node.style.strokeDasharray = "";
  }

  function apply() {
    svg.classList.toggle("fw-on", cur >= 0);
    svg.querySelectorAll(".fw-active").forEach((n) => {
      n.classList.remove("fw-active");
      n.querySelectorAll("rect").forEach(clearInline);
      n.style.animation = "";
    });
    svg.querySelectorAll(".fw-edge-active").forEach((n) => {
      n.classList.remove("fw-edge-active");
      if (n.tagName === "path") clearInline(n);
      else n.querySelectorAll("p, span, text").forEach((t) => { t.style.color = ""; t.style.fill = ""; });
    });

    if (cur >= 0) {
      const step = cfg.steps[cur];
      for (const n of step.nodes) {
        const g = nodeId(n);
        if (!g) continue;
        g.classList.add("fw-active");
        g.style.animation = "";
        g.querySelectorAll("rect").forEach((r) => {
          r.style.stroke = ACTIVE_STROKE;
          r.style.strokeWidth = "2.5px";
          r.style.fill = ACTIVE_FILL;
        });
      }
      for (const e of step.edges || []) {
        const p = edgePath(e);
        if (p) {
          p.classList.add("fw-edge-active");
          p.style.stroke = ACTIVE_STROKE;
          p.style.strokeWidth = "2.5px";
          p.style.strokeDasharray = "7 5";
        }
        const lab = edgeLabel(e);
        if (lab && lab.querySelector("p, text")) {
          lab.classList.add("fw-edge-active");
          lab.querySelectorAll("p, span, text").forEach((t) => {
            t.style.color = ACTIVE_STROKE;
            t.style.fill = ACTIVE_STROKE;
          });
        }
      }
    }

    // per-node visited/future dimming (CSS reads fw-done; current is fw-active)
    svg.querySelectorAll("g.node").forEach((g) => {
      g.classList.remove("fw-done");
    });
    if (cur >= 0) {
      for (const [suffix, first] of firstSeen) {
        if (first >= cur) continue;
        // a node is "done" only if it is not part of the current step
        if ((cfg.steps[cur].nodes || []).includes(suffix)) continue;
        const g = nodeId(suffix);
        if (g) g.classList.add("fw-done");
      }
    }

    pTitle.textContent = cur >= 0 ? (cur + 1) + " · " + cfg.steps[cur].title : "How to read this figure";
    pText.textContent = cur >= 0 ? cfg.steps[cur].text : cfg.intro;
    count.textContent = cur >= 0 ? "step " + (cur + 1) + " / " + cfg.steps.length : "0 / " + cfg.steps.length;
    dotEls.forEach((d, i) => {
      if (i === cur) d.setAttribute("aria-current", "step");
      else d.removeAttribute("aria-current");
      d.classList.toggle("fw-done", cur >= 0 && i < cur);
    });
  }

  function schedule() {
    clearTimeout(timer);
    timer = setTimeout(() => {
      if (!playing) return;
      if (cur + 1 < cfg.steps.length) {
        cur += 1;
        apply();
        schedule();
      } else {
        playing = false;
        syncToggle();
      }
    }, STEP_MS);
  }

  function syncToggle() {
    bToggle.textContent = playing ? "pause" : "play";
    bToggle.setAttribute("aria-label", playing ? "Pause" : "Play");
    bToggle.classList.toggle("fw-playing", playing);
  }

  function play() {
    if (playing) return;
    if (cur >= cfg.steps.length - 1) cur = -1; // at the end: play = replay
    playing = true;
    syncToggle();
    if (cur < 0) { cur = 0; apply(); }
    schedule();
  }
  function pause() {
    playing = false;
    clearTimeout(timer);
    syncToggle();
  }
  function go(i) {
    cur = Math.max(0, Math.min(cfg.steps.length - 1, i));
    apply();
  }

  bRestart.addEventListener("click", () => { pause(); cur = 0; apply(); play(); });
  bPrev.addEventListener("click", () => { pause(); if (cur >= 0) go(cur - 1); });
  bNext.addEventListener("click", () => { pause(); go(cur + 1); });
  bToggle.addEventListener("click", () => (playing ? pause() : play()));

  figure.append(stage, controls, panel);
  apply();

  // autoplay once the figure is actually on screen (and only if the visitor
  // has not asked for reduced motion — the controls still work)
  if (!window.matchMedia("(prefers-reduced-motion: reduce)").matches) {
    const io = new IntersectionObserver(
      (entries) => {
        for (const e of entries) {
          if (e.isIntersecting) {
            io.disconnect();
            play();
          }
        }
      },
      { threshold: 0.35 },
    );
    io.observe(figure);
  }
  // a hidden tab must not step silently
  document.addEventListener("visibilitychange", () => {
    if (document.hidden) pause();
  });
}

async function inlineSvg(img) {
  const src = img.getAttribute("src");
  const resp = await fetch(src);
  if (!resp.ok) throw new Error("fetch " + src + " → " + resp.status);
  const text = await resp.text();
  const holder = el("div", "fw-stage");
  holder.innerHTML = text;
  const svg = holder.querySelector("svg");
  if (!svg) throw new Error("no <svg> in " + src);
  return svg;
}

async function boot() {
  for (const figure of document.querySelectorAll("figure[data-walk]")) {
    const name = (figure.getAttribute("data-walk") || "").split("/").pop();
    const cfg = WALKS[name];
    const img = figure.querySelector('img[src$="/' + name + '"]');
    if (!cfg || !img) continue;
    try {
      const svg = await inlineSvg(img);
      const svgId = svg.id;
      if (!svgId) throw new Error(name + ": svg has no id");
      img.replaceWith(svg); // stage gets built around it in setupWalk
      setupWalk(figure, svg, svgId, cfg);
    } catch (err) {
      console.warn("[flow-walk] " + name + " stays static:", err.message);
    }
  }
}

boot();
